import pandas as pd


def clean(df):
    df = df.copy()
    # body_mass_g is stored as text with thousands separators (e.g. '3,150')
    df['body_mass_g'] = (
        df['body_mass_g']
        .astype(str)
        .str.replace(',', '', regex=False)
        .str.strip()
    )
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    return df


def answer(df):
    df = clean(df)
    grouped = df.groupby('species')['body_mass_g'].sum()
    result = {}
    for species, total in grouped.items():
        if pd.notna(species):
            result[species] = total
    return result
